    model: cfg.model,
    max_tokens: cfg.maxOutputTokens,
    temperature: 0,
    system,
    tools: [toolSpec(schema)],
    tool_choice: { type: 'tool', name: TOOL_NAME },
    messages: [{ role: 'user', content: `<transcript${attrs}>\n${fence(text)}\n</transcript>` }],
  };
