    model: cfg.model,
    max_tokens: cfg.maxOutputTokens,
    temperature: 0,
    system,
    tools: [toolSpec(schema)],
    tool_choice: { type: 'tool', name: TOOL_NAME },
    messages: [{ role: 'user', content: `<chunk_results>\n${fence(JSON.stringify(chunkResults, null, 2))}\n</chunk_results>` }],
  };
